/* Read-only design comparison. Changes here do not alter the backend assembly. */
let cacheLayout='current';
function seedPrompt(){return `<details class="prompt-text-block fixed source-memory"><summary><strong>初始化身份底色</strong><span class="prompt-kind">实例内稳定</span></summary><div class="prompt-text-content"><div class="prompt-attribution">${promptOwnerLink('memory')}<span>初始化时保存；不随每轮对话重写</span></div><p class="help">真实正文来自记忆库 memory_seed。本原型未连接实例，没有读取或伪造其内容。它与成长中的“当前自我认识”不是同一部分。</p></div></details>`;}
function promptRules(task){return fixedPrompt('工作与能力使用原则','core',PROMPT_COPY.harness,true)+(task?fixedPrompt('任务目标与执行','core',PROMPT_COPY.task[0])+fixedPrompt('任务推进与反馈','core',PROMPT_COPY.task[1])+fixedPrompt('完成、等待与留存想法','core',PROMPT_COPY.task[2])+fixedPrompt('事实与回执','core',PROMPT_COPY.task[3]):fixedPrompt('对经历留下自己的想法','memory',PROMPT_COPY.memory)+fixedPrompt('上下文数据的使用边界','core',PROMPT_COPY.context));}
function liveContextPreview(task){return `${dynamicPrompt('当前自我认识（记忆修订后更新）','memory')}${dynamicPrompt('按当前输入召回的记忆','memory')}${dynamicPrompt('近期自我摘要','memory')}${promptScene==='qq'?dynamicPrompt('同群观察窗口与背景消息','qq'):dynamicPrompt('任务目标、当前阶段与检查点','core')}${promptScene==='activity'?dynamicPrompt('本轮活动状态与继续条件','activity'):''}${dynamicPrompt('当前输入',task?'core':'qq')}`;}
function toolsPreview(proposal){return heading(proposal?'低频内容 · 工具定义（独立字段）':'能力与工具')+dynamicPrompt('已装配能力说明（随装配变化）','core')+dynamicPrompt('本轮获准调用的工具定义','dsh')+'<p class="help">工具定义位于独立 tools 字段。保持合法定义与排序稳定，不能为了缓存保留越权工具；该字段如何影响前缀由实际模型线路确认。</p>';}
function promptPreview(){const vision=promptScene==='vision',task=promptScene==='task'||promptScene==='activity',proposal=cacheLayout==='proposal';return `<div class="page-intro"><h2>提示词文本预览</h2><p>稳定底色与动态自我认识分开显示。固定文案可展开，动态正文只显示占位；颜色与模块名称用于只读标注。</p></div><div class="preview-controls"><label>请求场景<select id="prompt-scene" aria-label="提示词请求场景"><option value="qq" ${promptScene==='qq'?'selected':''}>QQ 对话</option><option value="task" ${promptScene==='task'?'selected':''}>主人任务</option><option value="activity" ${promptScene==='activity'?'selected':''}>自主活动</option><option value="vision" ${vision?'selected':''}>独立视觉分析</option></select></label><label>查看布局<select id="cache-layout" aria-label="查看提示词布局"><option value="current" ${proposal?'':'selected'}>当前代码 · 逻辑分层</option><option value="proposal" ${proposal?'selected':''}>缓存优化草案 · 待讨论</option></select></label></div>
 <div class="note">${proposal?'这是待讨论的布局草案，尚未改动实际请求。目标是稳定规则与工具定义、保留合法历史前缀，再追加本轮变化。':'这是源码层面的分层，不是供应商最终 Token 序列。当前最前方的身份底色来自初始化记忆，不是每轮更新的自我认识。'}</div>
 <div class="prompt-legend" aria-label="模块颜色图例">${Object.keys(promptOwners).filter(owner=>vision?owner==='media':owner!=='activity'||promptScene==='activity').map(promptOwnerLink).join('')}</div>
 <div class="prompt-document" aria-label="提示词渲染文本">${vision?`${heading('系统提示词')}${fixedPrompt('视觉观察规范','media',PROMPT_COPY.vision,true)}${heading('当前输入')}${dynamicPrompt('图像、位置与当前分析要求','media')}`:
 `${heading(proposal?'稳定内容 · 规则与身份底色':'系统提示词')}${proposal?promptRules(task)+seedPrompt():seedPrompt()+promptRules(task)}${promptScene==='qq'?`${heading('渠道固定约定')}${fixedPrompt('QQ 表达约定','qq',PROMPT_COPY.qq)}`:''}
 ${proposal?toolsPreview(true):''}
 ${proposal?`<div class="cache-plan"><strong>messages 的建议结构</strong><div class="assembly-flow"><span>已提交的合法历史</span><b>→</b><span>本轮新增输入与上下文</span></div><p>普通状态更新追加新快照，不回写早先消息。撤回、失效、越权内容仍必须退出请求；此时允许缓存前缀失效。</p></div>${heading('已提交历史 · 同一会话内尽量保持字节稳定')}${dynamicPrompt('已提交且仍允许使用的历史','core')}${heading('本轮新增上下文 · 允许变化')}`:heading('运行时上下文')}
 ${liveContextPreview(task)}
 ${proposal?'':toolsPreview(false)}
 ${heading(proposal?'后续工具结果 · 按实际发生顺序追加':'消息与调用结果')}${proposal?'':dynamicPrompt('会话与执行历史',task?'core':'qq')}${dynamicPrompt('DSH 工具结果（调用后）','dsh')}${dynamicPrompt('B站公开内容观察（调用后）','bili')}${dynamicPrompt('多媒体观察（调用后）','media')}${dynamicPrompt('系统执行回执（调用后）','executor')}`}</div>
 <details class="design-note"><summary>缓存讨论要点</summary><p>缓存匹配的是请求前缀，不能只看某个模块的文本是否相同。每轮重写早先的上下文载体，可能从那个位置开始破坏复用；把最新快照放在全部历史前面也有相同问题。</p><p>初始底色在实例内稳定；自我认识按记忆版本更新；每轮召回和观察属于动态尾部。权限撤销、资料撤回和必要压缩优先于缓存复用。</p><p>实际命中需要观察模型线路返回的缓存用量，本原型没有调用模型或声称已经实现缓存优化。</p></details>`;}
document.addEventListener('change',event=>{if(event.target.id==='cache-layout'){cacheLayout=event.target.value;render();}});
